select , 
  from sdsorder.u_o_orderdetail_${tableSuffix}
 where shop_code = #{shopCode}
   and ordercode in
   #{code}
 order by ordercode, lineno, detailcode

select , 
  from sdsorder.u_o_orderdetail_${tableSuffix}
 where shop_code = #{shopCode}
   and coalesce(shippedqty, 0) > 0
 order by ordercode, lineno, detailcode

select , 
  from sdsorder.u_o_orderdetail_${tableSuffix}
 where shop_code = #{shopCode} and ordercode = #{orderCode}
 order by lineno, detailcode
 for update

select , 
  from sdsorder.u_o_orderdetail_${tableSuffix}
 where shop_code = #{shopCode} and detailcode = #{detailCode}
 for update

mapper.update:
update sdsorder.u_o_orderdetail_${tableSuffix}
   set shippedqty = coalesce(shippedqty, 0) + #{delta},
       remainingqty = qty - shippedqty
 where shop_code = #{shopCode} and detailcode = #{detailCode}
   and (coalesce(shippedqty, 0) + #{delta}) >= 0
   and (coalesce(shippedqty, 0) + #{delta}) <= qty

update sdsorder.u_o_orderdetail_${tableSuffix}
   set sourcecode = #{sourceCode}
 where shop_code = #{shopCode} and detailcode = #{detailCode}
